func run(args []string, db *gorm.DB) error {
	if len(args) == 0 {
		return nil
	}

	cmd := args[0]
	switch cmd {
	case "send":
		return handleSend(args[1:], db)
	case "list":
		return handleList(args[1:], db)
	case "archive":
		return handleArchive(args[1:], db)
	case "watch":
		return handleWatch(args[1:], db)
