func handleSend(args []string, db *gorm.DB) error {
	var from, to, subject, priority, msgType, body string
	for i := 0; i < len(args); i++ {
		switch args[i] {
		case "--from":
			if i+1 < len(args) {
				from = args[i+1]
				i++
			}
		case "--to":
			if i+1 < len(args) {
				to = args[i+1]
				i++
			}
		case "--subject":
			if i+1 < len(args) {
				subject = args[i+1]
				i++
			}
		case "--priority":
			if i+1 < len(args) {
				priority = args[i+1]
				i++
			}
		case "--type":
			if i+1 < len(args) {
				msgType = args[i+1]
				i++
			}
		case "--body":
			if i+1 < len(args) {
				body = args[i+1]
				i++
			}
		}
	}

	if from == "" {
		return errors.New("missing required flag: --from")
	}
	if to == "" {
		return errors.New("missing required flag: --to")
	}

	msg := &inbox.Message{
		ID:       uuid.New().String(),
		From:     from,
		To:       to,
		Subject:  subject,
		Priority: priority,
		Type:     msgType,
		Body:     body,
		Archived: false,
	}

	return db.Create(msg).Error
}

func handleList(args []string, db *gorm.DB) error {
	var agent string
	for i := 0; i < len(args); i++ {
		if args[i] == "--agent" && i+1 < len(args) {
			agent = args[i+1]
			i++
		}
	}

	var messages []inbox.Message
	err := db.Where("to = ? AND archived = ?", agent, false).Find(&messages).Error
	if err != nil {
		return err
	}

	for _, m := range messages {
		fmt.Printf("ID: %s | From: %s | Subject: %s\n", m.ID, m.From, m.Subject)
	}
	return nil
}

func handleArchive(args []string, db *gorm.DB) error {
	var id string
	for i := 0; i < len(args); i++ {
		if args[i] == "--id" && i+1 < len(args) {
			id = args[i+1]
			i++
		}
	}

	if id == "" {
		return errors.New("missing required flag: --id")
	}

	return db.Model(&inbox.Message{}).Where("id = ?", id).Update("archived", true).Error
}

func handleWatch(args []string, db *gorm.DB) error {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	// Simulate watching by waiting for context cancellation
	select {
	case <-ctx.Done():
		return nil
	}
