		{ID: "1", From: "alice", To: "mike", Subject: "Msg 1", Archived: false},
		{ID: "2", From: "bob", To: "mike", Subject: "Msg 2", Archived: false},
		{ID: "3", From: "charlie", To: "mike", Subject: "Archived Msg", Archived: true},
